function minWindow(s, t) {
  const need = new Map();                            // char -> how many more the window needs
  for (const ch of t) need.set(ch, (need.get(ch) ?? 0) + 1);
  let missing = t.length;                            // characters of t not yet covered
  let left = 0, bestStart = 0, bestLen = Infinity;
  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    if (need.has(ch)) {
      if (need.get(ch) > 0) missing--;               // this one was still needed
      need.set(ch, need.get(ch) - 1);                // (below 0 means a spare copy)
    }
    while (missing === 0) {                          // the window covers t: try to shrink it
      if (right - left + 1 < bestLen) {
        bestStart = left;
        bestLen = right - left + 1;
      }
      const out = s[left++];
      if (need.has(out)) {
        need.set(out, need.get(out) + 1);
        if (need.get(out) > 0) missing++;            // dropped a character we still needed
      }
    }
  }
  return bestLen === Infinity ? "" : s.slice(bestStart, bestStart + bestLen);
}

def min_window(s, t):
    need = {}                             # char -> how many more the window needs
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    missing = len(t)                      # characters of t not yet covered
    left = best_start = 0
    best_len = float("inf")
    for right, ch in enumerate(s):
        if ch in need:
            if need[ch] > 0:
                missing -= 1              # this one was still needed
            need[ch] -= 1                 # (below 0 means a spare copy)
        while missing == 0:               # the window covers t: try to shrink it
            if right - left + 1 < best_len:
                best_start, best_len = left, right - left + 1
            out = s[left]
            left += 1
            if out in need:
                need[out] += 1
                if need[out] > 0:
                    missing += 1          # dropped a character we still needed
    return "" if best_len == float("inf") else s[best_start:best_start + best_len]

String minWindow(String s, String t) {
    int[] need = new int[128];                   // char -> how many more the window needs
    for (char ch : t.toCharArray()) need[ch]++;
    int missing = t.length();                    // characters of t not yet covered
    int left = 0, bestStart = 0, bestLen = Integer.MAX_VALUE;
    for (int right = 0; right < s.length(); right++) {
        if (need[s.charAt(right)]-- > 0) missing--;   // was still needed (others go below 0)
        while (missing == 0) {                   // the window covers t: try to shrink it
            if (right - left + 1 < bestLen) {
                bestStart = left;
                bestLen = right - left + 1;
            }
            if (++need[s.charAt(left++)] > 0) missing++;   // dropped a character we still needed
        }
    }
    return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestStart, bestStart + bestLen);
}

